# WARNING: Under review - generated by LLM.

"""True 390px dark-viewport render gate for the Week 4 course pages.

scrollWidth equality alone is not enough: a page can report no overflow while
headings/prose still sit outside the visible viewport.  This gate drives a
real headless Chrome at a true 390px viewport in dark mode and asserts:

- body/document scrollWidth equals the viewport width (no page overflow);
- the content box spans exactly the viewport (left >= 0, right <= viewport);
- every visible element inside ``main`` has left >= 0 and right <= viewport,
  unless it is inside an intentional contained-scroll wrapper (the default
  mdBook ``.table-wrapper``).

The gate skips when Chrome or websocket-client is unavailable so it can run
in CI where a browser exists and be skipped elsewhere.
"""

import json
import shutil
import subprocess
import time
import urllib.request
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
BOOK = ROOT / "book" / "book"

PAGES = (
    "week4-01-agent-loop.html",
    "week4-overview.html",
    "week2-02-benchmark-profile.html",
    "week3-02-chunked-prefill.html",
)

CHROME_CANDIDATES = (
    "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
    "/usr/bin/google-chrome",
    "/usr/bin/chromium",
    "/usr/bin/chromium-browser",
)


def _find_chrome():
    for candidate in CHROME_CANDIDATES:
        if Path(candidate).exists():
            return candidate
    found = shutil.which("google-chrome") or shutil.which("chromium")
    return found


@pytest.mark.skipif(_find_chrome() is None, reason="no headless Chrome available")
@pytest.mark.parametrize("page", PAGES)
def test_390px_dark_render_is_fully_visible(page):
    try:
        import websocket  # noqa: F401
    except ImportError:
        pytest.skip("websocket-client unavailable")

    html = BOOK / page
    if not html.exists():
        pytest.skip(f"{page} not built; run mdbook build book first")

    chrome = _find_chrome()
    port = 9236
    proc = subprocess.Popen(
        [
            chrome,
            "--headless",
            "--disable-gpu",
            f"--remote-debugging-port={port}",
            "--remote-allow-origins=*",
            "--force-dark-mode",
            f"file://{html}",
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    try:
        deadline = time.monotonic() + 10
        targets = None
        while time.monotonic() < deadline:
            try:
                targets = json.loads(
                    urllib.request.urlopen(
                        f"http://127.0.0.1:{port}/json", timeout=1
                    ).read()
                )
                break
            except Exception:
                time.sleep(0.3)
        assert targets, "chrome debugging endpoint did not come up"
        page_target = next(t for t in targets if t["type"] == "page")
        ws = websocket.create_connection(
            page_target["webSocketDebuggerUrl"], timeout=10
        )

        def cmd(method, params=None):
            ws.send(json.dumps({"id": 1, "method": method, "params": params or {}}))
            while True:
                msg = json.loads(ws.recv())
                if msg.get("id") == 1:
                    return msg

        cmd(
            "Emulation.setDeviceMetricsOverride",
            {"width": 390, "height": 800, "deviceScaleFactor": 1, "mobile": False},
        )
        time.sleep(0.8)
        expr = """(() => {
            const vw = document.documentElement.clientWidth;
            const content = document.querySelector('.content');
            const contentRect = content ? content.getBoundingClientRect() : null;
            const clipped = [];
            for (const el of document.querySelectorAll('main *')) {
                const r = el.getBoundingClientRect();
                const cs = getComputedStyle(el);
                if (r.width <= 0 || r.height <= 0 || cs.visibility === 'hidden') continue;
                // inside an intentional contained-scroll container?
                // (mdBook table-wrapper, or pre/code with overflow-x: auto)
                let insideScroll = false;
                let p = el.parentElement;
                while (p) {
                    const ps = getComputedStyle(p);
                    const isScrollContainer =
                        (p.classList && p.classList.contains('table-wrapper')) ||
                        (p.tagName === 'PRE' && ps.overflowX === 'auto') ||
                        (p.tagName === 'CODE' && ps.overflowX === 'auto');
                    if (isScrollContainer) {
                        insideScroll = true;
                        break;
                    }
                    p = p.parentElement;
                }
                if (!insideScroll && (r.left < -2 || r.right > vw + 2)) {
                    clipped.push({tag: el.tagName, left: Math.round(r.left),
                                  right: Math.round(r.right),
                                  text: (el.textContent||'').slice(0,40).replace(/\\s+/g,' ')});
                    if (clipped.length >= 8) break;
                }
            }
            return {
                viewport: vw,
                bodyScroll: document.body.scrollWidth,
                docScroll: document.documentElement.scrollWidth,
                contentLeft: contentRect ? Math.round(contentRect.left) : null,
                contentRight: contentRect ? Math.round(contentRect.right) : null,
                clippedCount: clipped.length,
                clipped,
            };
        })()"""
        r = cmd("Runtime.evaluate", {"expression": expr, "returnByValue": True})
        value = r["result"]["result"].get("value", {})
        ws.close()

        assert value["bodyScroll"] == value["docScroll"] == value["viewport"], (
            f"{page}: page overflow (body {value['bodyScroll']} vs viewport "
            f"{value['viewport']})"
        )
        if value["contentLeft"] is not None:
            assert value["contentLeft"] >= 0, f"{page}: content starts off-screen left"
            assert value["contentRight"] <= value["viewport"] + 2, (
                f"{page}: content extends past the viewport right edge"
            )
        assert value["clippedCount"] == 0, (
            f"{page}: {value['clippedCount']} visible elements clipped: "
            f"{value['clipped']}"
        )
    finally:
        proc.terminate()
        proc.wait(timeout=5)
